import {test,expect} from 'bun:test';
import {mkdtempSync,rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {CoreExecutionJournal} from './core-execution';
import {CoreDeliveryAdmission} from './core-delivery-admission';
import type {DeliveryRecord} from './core-delivery';
function fixture(){const dir=mkdtempSync(join(tmpdir(),'mind-admission-proof-')),journal=new CoreExecutionJournal(dir);let proof=new CoreDeliveryAdmission(dir,journal);const principal={moduleId:'mind',hash:'b'.repeat(40)},author={moduleId:'author',hash:'a'.repeat(40)};const e=journal.prepare({purpose:'pursuit',subject:'goal',revision:1,visibilityRevision:0,prompt:'material',tools:['modules.admit'],principal},new Date().toISOString());Object.assign(e,{runId:'run',contextId:'context',status:'settling',ended:true,active:false,terminalStatus:'finished'});e.facts=[{runId:'run',callId:'selected',target:'modules.admit',moduleId:'system:modules',hash:'kernel-contract-hash',status:'succeeded',outputState:'complete',output:{admissionId:'admission',requestKey:'original-admission-key',submitter:author,targets:[{name:'calendar',moduleId:null,expectedActiveHash:null}]}}];journal.save(e);const record={admissionId:'admission',author,worker:{executionId:e.id,runId:'run',principal},materials:[{name:'calendar',materialDigest:'c'.repeat(64)}]} as DeliveryRecord;return {e,journal,record,get proof(){return proof;},reopen(){proof.close();proof=new CoreDeliveryAdmission(dir,journal);},close(){proof.close();journal.close();rmSync(dir,{recursive:true,force:true});}};}
test('selected original admission survives worker result cleanup and restart; exact targets and principal remain bound',()=>{const f=fixture();try{expect(f.proof.capture(f.e)).toBe(1);f.e.facts=[];f.e.settled=true;f.journal.save(f.e);f.reopen();expect(()=>f.proof.verify(f.record)).not.toThrow();expect(()=>f.proof.verify({...f.record,materials:[{name:'other',materialDigest:'c'.repeat(64)}]})).toThrow('exact');expect(()=>f.proof.verify({...f.record,worker:{...f.record.worker,runId:'new-run'}})).toThrow('exact');}finally{f.close();}});
test('forged argument copy, unselected target, wrong invoking run and failed terminal cannot mint a handoff proof',()=>{const f=fixture();try{const forged=structuredClone(f.e);forged.facts[0]!.callId='forged';expect(f.proof.capture(forged)).toBe(0);for(const mutation of [(e:typeof f.e)=>{e.tools=[];},(e:typeof f.e)=>{e.facts[0]!.runId='other';},(e:typeof f.e)=>{e.facts[0]!.moduleId='mind';},(e:typeof f.e)=>{e.terminalStatus='failed';},(e:typeof f.e)=>{(e.facts[0]!.output as any).targets[0].moduleId='existing';}]){const e=structuredClone(f.e);mutation(e);f.journal.save(e);expect(f.proof.capture(e)).toBe(0);}expect(()=>f.proof.verify(f.record)).toThrow('unavailable');}finally{f.close();}});
